questions.text:
¿Qué se muestra en consola al ejecutar el siguiente código?

<h1 id="titulo">Hola</h1>

<script>
let elemento = document.getElementById("titulo");
console.log(elemento.textContent);
</script>

¿Qué verá el usuario en la página después de ejecutar el código?

<p id="mensaje">Texto original</p>

<script>
let mensaje = document.getElementById("mensaje");
mensaje.textContent = "Texto modificado";
</script>

¿Qué ocurre después de ejecutar el siguiente código JavaScript?

<p id="mensaje">Hola</p>

<script>
let elemento = document.getElementById("mensaje");
elemento.style.color = "red";
</script>

¿Qué ocurre cuando el usuario presiona el botón?

<button id="boton">Presionar</button>
<p id="resultado"></p>

<script>
let boton = document.getElementById("boton");

boton.addEventListener("click", function() {
    document.getElementById("resultado").textContent = "Botón presionado";
});
</script>

¿Qué valor se muestra en consola?

<input id="nombre" value="Carlos">

<script>
let nombre = document.getElementById("nombre").value;
console.log(nombre);
</script>

¿Qué hace el siguiente código JavaScript?

let nuevoParrafo = document.createElement("p");
nuevoParrafo.textContent = "Nuevo contenido";

document.body.appendChild(nuevoParrafo);

¿Qué se mostrará al renderizar el componente App?

function Saludo() {
    return <h1>Hola estudiantes</h1>;
}

function App() {
    return <Saludo />;
}

¿Qué se mostrará en pantalla al renderizar el componente App?

function Estudiante(props) {
    return <p>{props.nombre}</p>;
}

function App() {
    return <Estudiante nombre="Carlos" />;
}

¿Qué se mostrará en la plantilla HTML de Angular?

// app.component.ts
export class AppComponent {
    nombre = "Carlos";
}

// app.component.html
<h1>Hola {{ nombre }}</h1>

Si el usuario presiona el botón dos veces, ¿qué valor se mostrará en el párrafo?

// app.component.ts
export class AppComponent {
    contador = 0;

    incrementar() {
        this.contador++;
    }
}

// app.component.html
<button (click)="incrementar()">Incrementar</button>
<p>{{ contador }}</p>

¿Qué efecto tendrá el siguiente CSS sobre el párrafo?

<p class="destacado">Bienvenido</p>

<style>
.destacado {
    font-weight: bold;
}
</style>

¿Qué ocurrirá al ejecutar el siguiente JavaScript?

<div id="contenedor"></div>

<script>
let contenedor = document.getElementById("contenedor");

let boton = document.createElement("button");
boton.textContent = "Guardar";

contenedor.appendChild(boton);
</script>

¿Qué contenido se renderizará en pantalla?

function Producto({ nombre, precio }) {
    return (
        <p>
            {nombre} - ${precio}
        </p>
    );
}

function App() {
    return <Producto nombre="Teclado" precio={25} />;
}
